@pytest.fixture(scope="module", name="foundation")
def fixture_foundation(tmp_path_factory):
    return water_foundation(tmp_path_factory.mktemp("water_foundation"))


@pytest.fixture(name="loaded")
def fixture_loaded(foundation, fp64):
    return read_foundation(foundation, DEFAULT_CATALOGUE)


@pytest.fixture(name="fp64")
def fixture_fp64():
    previous = torch.get_default_dtype()
    torch.set_default_dtype(torch.float64)
    try:
        yield
    finally:
        torch.set_default_dtype(previous)


def replay_structures(count=6, seed=11, stress=False):
    generator = np.random.default_rng(seed)
    frames = []
    for _ in range(count):
        atoms = Atoms(
            "OH2",
            positions=WATER + generator.normal(scale=0.05, size=(3, 3)),
            cell=np.eye(3) * 6.0,
            pbc=True,
        )
        atoms.info["REF_energy"] = 99.0
        atoms.arrays["REF_forces"] = np.full((3, 3), 7.0)
        if stress:
            atoms.info["REF_stress"] = np.full(6, 0.5)
        frames.append(atoms)
    return frames


def configurations(count=4, stress_weight=None):
    generator = np.random.default_rng(3)
    items = []
    for index in range(count):
        properties = {
            "energy": 99.0,
            "forces": np.full((3, 3), 7.0),
            "stress": None,
        }
        weights = {"energy": 1.0, "forces": 1.0, "stress": 0.0}
        if stress_weight is not None and index % 2 == 0:
            properties["stress"] = np.full((3, 3), 0.5)
            weights["stress"] = stress_weight
        items.append(
            Configuration(
                atomic_numbers=np.array([8, 1, 1]),
                positions=WATER + generator.normal(scale=0.05, size=(3, 3)),
                properties=properties,
                property_weights=weights,
                cell=np.eye(3) * 6.0,
                pbc=(True, True, True),
                config_type="water",
                head="replay",
            )
        )
    return items


def label(loaded, items, spec=SPEC, batch_size=3, engine=None):
    return generate_pseudolabels(
        engine or loaded.engine,
        items,
        spec,
        z_table=loaded.z_table,
        cutoff=loaded.config.model.r_max,
        head_index=0,
        batch_size=batch_size,
    )


def fine_tune(directory, foundation, **finetune):
    directory.mkdir(parents=True, exist_ok=True)
    write(directory / "replay.xyz", replay_structures())
    write(directory / "new.xyz", waters(8, seed=4))
    pseudolabels = finetune.pop("pseudolabels", {"enabled": True, "heads": ["replay"]})
    return ResolvedConfig.model_validate(
        {
            "runtime": {"work_dir": str(directory), "seed": 5},
            "finetune": {
                "foundation_model": str(foundation),
                "pseudolabels": pseudolabels,
                **finetune,
            },
            "data": {
                "heads": {
                    "replay": {"train_file": str(directory / "replay.xyz")},
                    "new": {
                        "train_file": str(directory / "new.xyz"),
                        "e0s": {"kind": "isolated_atoms"},
                    },
                },
                "valid_fraction": 0.25,
                "pin_memory": False,
            },
            "model": {"observables": ["energy", "forces"]},
            "training": {"max_num_epochs": 1, "batch_size": 4},
        }
    )


# ---------------------------------------------------------------------------
# Generating them
# ---------------------------------------------------------------------------


def test_the_labels_are_the_foundation_model_s_own(loaded):
    items = configurations()
    labelled = label(loaded, items)
    from mace_torch.data import collate_training
    from mace_torch.data.batch import GraphDataset

    dataset = GraphDataset(
        items, cutoff=loaded.config.model.r_max, z_table=loaded.z_table, targets=()
    )
    batch = collate_training(
        [dataset[i] for i in range(len(items))], z_table=loaded.z_table
    )
    direct = loaded.engine(dict(batch.graph), compute=("forces",))
    energies = np.array([item.properties["energy"] for item in labelled])
    forces = np.concatenate([item.properties["forces"] for item in labelled])
    np.testing.assert_allclose(
        energies, direct.total_energy.detach().numpy(), atol=1e-12
    )
    np.testing.assert_allclose(forces, direct.forces.detach().numpy(), atol=1e-12)
    assert all(item.properties["energy"] != 99.0 for item in labelled)


def test_generating_changes_neither_the_structures_nor_the_model(loaded):
    items = configurations()
    before = [dict(item.properties) for item in items]
    flags = [parameter.requires_grad for parameter in loaded.engine.parameters()]
    label(loaded, items)
    assert all(item.properties["energy"] == 99.0 for item in items)
    assert [set(item.properties) for item in items] == [set(p) for p in before]
    assert [
        parameter.requires_grad for parameter in loaded.engine.parameters()
    ] == flags
    assert all(parameter.grad is None for parameter in loaded.engine.parameters())


def saved_bytes(call) -> int:
    """What autograd holds for the backward pass while ``call`` runs."""
    total = [0]

    def pack(tensor):
        total[0] += tensor.numel() * tensor.element_size()
        return tensor

    with torch.autograd.graph.saved_tensors_hooks(pack, lambda tensor: tensor):
        call()
    return total[0]


def test_the_weights_are_constants_while_labelling(loaded):
    """No activation is kept for a weight gradient: the stage holds what the
    model holds with every parameter frozen, and less than with none."""
    items = configurations(1)
    from mace_torch.data import collate_training
    from mace_torch.data.batch import GraphDataset

    dataset = GraphDataset(
        items, cutoff=loaded.config.model.r_max, z_table=loaded.z_table, targets=()
    )
    graph = dict(collate_training([dataset[0]], z_table=loaded.z_table).graph)

    def direct():
        loaded.engine(dict(graph), compute=("forces",), training=False)

    trainable = saved_bytes(direct)
    for parameter in loaded.engine.parameters():
        parameter.requires_grad_(False)
    try:
        frozen = saved_bytes(direct)
    finally:
        for parameter in loaded.engine.parameters():
            parameter.requires_grad_(True)
    labelling = saved_bytes(lambda: label(loaded, items, batch_size=1))
    assert labelling == frozen < trainable
    assert all(parameter.requires_grad for parameter in loaded.engine.parameters())


def test_a_caller_without_gradients_still_gets_forces(loaded):
    """A force is a gradient, so the stage cannot run under ``torch.no_grad()``
    the way the frozen tree's switching off suggests; it turns them on for
    itself and gives the same labels."""
    items = configurations()
    expected = label(loaded, items)
    with torch.no_grad():
        labelled = label(loaded, items)
    for one, two in zip(expected, labelled, strict=True):
        assert np.array_equal(one.properties["forces"], two.properties["forces"])


class _FailsOnSecondCall(torch.nn.Module):
    """The foundation model, until the second batch runs out of memory."""

    def __init__(self, inner):
        super().__init__()
        self.inner = inner
        self.calls = 0

    def forward(self, graph, compute, training):
        self.calls += 1
        if self.calls == 2:
            raise RuntimeError("out of memory")
        return self.inner(graph, compute=compute, training=training)


def test_a_failing_batch_stops_everything(loaded):
    with pytest.raises(PseudolabelError, match="batch 2 of 2"):
        label(loaded, configurations(), engine=_FailsOnSecondCall(loaded.engine))


def test_a_stress_keeps_the_weight_its_file_gave_it(loaded):
    spec = SPEC.model_copy(update={"properties": ("energy", "forces", "stress")})
    labelled = label(loaded, configurations(stress_weight=0.3), spec)
    assert [item.property_weights["stress"] for item in labelled] == [
        0.3,
        0.0,
        0.3,
        0.0,
    ]
    assert labelled[1].properties["stress"] is None

    forced = spec.model_copy(update={"stress_if_missing": True})
    labelled = label(loaded, configurations(stress_weight=0.3), forced)
    assert [item.property_weights["stress"] for item in labelled] == [
        0.3,
        1.0,
        0.3,
        1.0,
    ]
    assert labelled[1].properties["stress"].shape == (3, 3)


def test_a_property_the_model_does_not_produce_is_refused(loaded):
    spec = SPEC.model_copy(update={"properties": ("energy", "dipole")})
    with pytest.raises(PseudolabelError, match="dipole"):
        label(loaded, configurations(), spec)


