# The artifact
# ---------------------------------------------------------------------------


def provenance(loaded, items, **overrides):
    from datetime import UTC, datetime

    from mace_core.config import PseudolabelProvenance

    values = {
        "foundation_model": loaded.name,
        "foundation_fingerprint": foundation_fingerprint(loaded.name),
        "dataset_fingerprint": structures_fingerprint(items),
        "head": "replay",
        "foundation_head": "pbe",
        "spec": SPEC,
        "device": "cpu",
        "dtype": "float64",
        "torch_version": torch.__version__,
        "kernel_backend": "reference",
        "generated_at": datetime(2026, 9, 25, tzinfo=UTC),
        "n_configs": len(items),
        "deterministic": True,
        **overrides,
    }
    return PseudolabelProvenance(**values)


def test_the_artifact_reads_back_exactly(loaded, tmp_path):
    spec = SPEC.model_copy(update={"properties": ("energy", "forces", "stress")})
    labelled = label(loaded, configurations(stress_weight=0.3), spec)
    labelled[1] = Configuration(
        atomic_numbers=labelled[1].atomic_numbers,
        positions=labelled[1].positions,
        properties={**labelled[1].properties, "head": "replay"},
        property_weights=labelled[1].property_weights,
        cell=None,
        pbc=None,
        weight=0.25,
        config_type="odd",
        head="replay",
    )
    record = provenance(loaded, labelled)
    write_pseudolabel_artifact(tmp_path / "replay", labelled, record)
    back, read = load_pseudolabel_artifact(tmp_path / "replay")
    assert read == record
    assert len(back) == len(labelled)
    for written, again in zip(labelled, back, strict=True):
        assert np.array_equal(written.atomic_numbers, again.atomic_numbers)
        assert np.array_equal(written.positions, again.positions)
        assert written.weight == again.weight
        assert written.config_type == again.config_type
        assert written.head == again.head
        assert written.pbc == again.pbc
        assert (written.cell is None) == (again.cell is None)
        assert written.property_weights == again.property_weights
        assert set(written.properties) == set(again.properties)
        for name, value in written.properties.items():
            other = again.properties[name]
            if value is None or isinstance(value, str):
                assert other == value, name
            else:
                assert np.array_equal(np.asarray(value), np.asarray(other)), name
                assert type(value) is type(other) or isinstance(other, np.ndarray)


def test_a_directory_that_is_not_an_artifact_is_refused(tmp_path):
    with pytest.raises(PseudolabelError, match="not a pseudolabel artifact"):
        load_pseudolabel_artifact(tmp_path)


def test_reuse_is_refused_for_another_model_or_other_structures(loaded):
    items = configurations()
    record = provenance(loaded, items)
    right = {
        "foundation_fingerprint": record.foundation_fingerprint,
        "dataset_fingerprint": record.dataset_fingerprint,
    }
    validate_pseudolabel_reuse(record, **right)
    with pytest.raises(PseudolabelError, match="weights"):
        validate_pseudolabel_reuse(
            record, **{**right, "foundation_fingerprint": "0" * 64}
        )
    moved = configurations()
    moved[0].positions = moved[0].positions + 1e-9
    with pytest.raises(PseudolabelError, match="other structures"):
        validate_pseudolabel_reuse(
            record, **{**right, "dataset_fingerprint": structures_fingerprint(moved)}
        )


def test_version_drift_warns_only_for_labels_that_cannot_be_made_again(loaded):
    items = configurations()
    later = {"torch_version": "9.9.9", "kernel_backend": "reference"}
    for deterministic, expected in ((True, 0), (False, 1)):
        record = provenance(loaded, items, deterministic=deterministic)
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            validate_pseudolabel_reuse(
                record,
                foundation_fingerprint=record.foundation_fingerprint,
                dataset_fingerprint=record.dataset_fingerprint,
                **later,
            )
        assert len(caught) == expected


# ---------------------------------------------------------------------------
# In a run
# ---------------------------------------------------------------------------


def test_a_run_writes_its_labels_into_its_own_directory(
    foundation, loaded, tmp_path, monkeypatch
):
    monkeypatch.chdir(tmp_path)
    monkeypatch.setenv("XDG_CACHE_HOME", str(tmp_path / "cache"))
    config = fine_tune(tmp_path / "run", foundation)
    built = build(config)
    artifact = tmp_path / "run" / "pseudolabels" / "replay"
    labelled, record = load_pseudolabel_artifact(artifact)
    assert record.foundation_head == "pbe"
    assert record.n_configs == len(labelled) == 6
    assert record.deterministic
    assert all(item.properties["energy"] != 99.0 for item in labelled)
    assert not (tmp_path / "cache").exists()
    assert sorted(path.name for path in tmp_path.iterdir()) == ["run"]
    assert dict(built.data.e0s.values["replay"]) == dict(loaded.e0s["pbe"])


def test_a_later_run_reuses_them_by_naming_them(foundation, tmp_path):
    first = fine_tune(tmp_path / "first", foundation)
    build(first)
    labels = tmp_path / "first" / "pseudolabels"
    reused = fine_tune(
        tmp_path / "second",
        foundation,
        pseudolabels={"labels_from": str(labels), "heads": ["replay"]},
    )
    trained = run(reused)
    assert trained.checkpoint_path is not None
    assert not (tmp_path / "second" / "pseudolabels").exists()


def test_labels_for_other_structures_are_refused(foundation, tmp_path):
    first = fine_tune(tmp_path / "first", foundation)
    build(first)
    other = fine_tune(
        tmp_path / "second",
        foundation,
        pseudolabels={
            "labels_from": str(tmp_path / "first" / "pseudolabels"),
            "heads": ["replay"],
        },
    )
    write(tmp_path / "second" / "replay.xyz", replay_structures(seed=12))
    with pytest.raises(PseudolabelError, match="other structures"):
        build(other)


def test_the_standalone_step_writes_what_a_run_writes(foundation, tmp_path):
    config = fine_tune(tmp_path / "run", foundation)
    written = pseudolabel(config, "replay", tmp_path / "sweep")
    alone, alone_record = load_pseudolabel_artifact(written / "replay")
    build(config)
    in_run, run_record = load_pseudolabel_artifact(
        tmp_path / "run" / "pseudolabels" / "replay"
    )
    assert alone_record.dataset_fingerprint == run_record.dataset_fingerprint
    assert json.loads((written / "replay" / "manifest.json").read_text()) == json.loads(
        (tmp_path / "run" / "pseudolabels" / "replay" / "manifest.json").read_text()
    )
    for one, two in zip(alone, in_run, strict=True):
        assert one.properties["energy"] == two.properties["energy"]
    reused = fine_tune(
        tmp_path / "second",
        foundation,
        pseudolabels={"labels_from": str(written), "heads": ["replay"]},
    )
    assert run(reused).checkpoint_path is not None


def test_a_relabelled_head_with_no_structures_is_refused(foundation, tmp_path):
    config = fine_tune(tmp_path / "run", foundation)
    write(tmp_path / "run" / "replay.xyz", [])
    with pytest.raises(DataStageError, match="replay"):
        build(config)


