def resolved(**sections):
    return ResolvedConfig.model_validate(
        {
            "finetune": {"foundation_model": "fm.json", **sections.pop("finetune", {})},
            "data": {
                "heads": {
                    "replay": {"curated": "mp"},
                    "new": {"train_file": "new.xyz"},
                }
            },
            **sections,
        }
    )


def test_the_multihead_preset_fills_in_what_is_not_written():
    config = resolved(finetune={"preset": "multihead"})
    assert config.training.lr == 1e-4
    assert config.training.ema.enabled and config.training.ema.decay == 0.99999
    assert config.finetune.pseudolabels.enabled
    assert config.finetune.pseudolabels.properties == ("energy", "forces")
    assert config.pseudolabelled_heads == ("replay",)
    assert config.finetune.preset_values == {
        "training.lr": "multihead",
        "training.ema": "multihead",
        "finetune.pseudolabels.enabled": "multihead",
    }
    assert ResolvedConfig.model_validate(config.model_dump(mode="json")) == config


def test_a_written_value_always_wins_over_the_preset():
    config = resolved(
        finetune={"preset": "multihead", "pseudolabels": {"enabled": False}},
        training={"lr": 0.005, "ema": {"enabled": False}},
    )
    assert config.training.lr == 0.005
    assert not config.training.ema.enabled
    assert not config.finetune.pseudolabels.enabled
    assert config.finetune.preset_values == {}


def test_there_is_no_flag_that_forces_a_preset():
    from mace_core.config.pseudolabels import PseudolabelConfig
    from mace_core.config.resolved import FinetuneConfig
    from mace_core.config.training import TrainingConfig

    fields = [
        name
        for section in (FinetuneConfig, PseudolabelConfig, TrainingConfig)
        for name in section.model_fields
    ]
    assert not [name for name in fields if "force" in name]


def test_a_relabelled_head_takes_the_foundation_s_energies():
    config = resolved(finetune={"pseudolabels": {"enabled": True}})
    assert config.data.heads["replay"].e0s.kind == "foundation"
    assert config.data.heads["new"].e0s.kind == "isolated_atoms"
    with pytest.raises(ValueError, match="kind 'foundation'"):
        ResolvedConfig.model_validate(
            {
                "finetune": {
                    "foundation_model": "fm.json",
                    "pseudolabels": {"enabled": True},
                },
                "data": {
                    "heads": {"replay": {"curated": "mp", "e0s": {"kind": "average"}}}
                },
            }
        )


def test_generating_and_reusing_at_once_is_refused():
    with pytest.raises(ValueError, match="Set one"):
        resolved(finetune={"pseudolabels": {"enabled": True, "labels_from": "x"}})


def test_labels_need_a_foundation_model_and_a_head():
    with pytest.raises(ValueError, match="foundation_model"):
        ResolvedConfig.model_validate(
            {
                "finetune": {"pseudolabels": {"enabled": True}},
                "data": {"heads": {"replay": {"curated": "mp"}}},
            }
        )
    with pytest.raises(ValueError, match="no head is relabelled"):
        ResolvedConfig.model_validate(
            {
                "finetune": {
                    "foundation_model": "fm.json",
                    "pseudolabels": {"enabled": True},
                },
                "data": {"heads": {"new": {"train_file": "new.xyz"}}},
            }
        )


def test_the_legacy_flags_land_on_the_section():
    from argparse import Namespace

    from mace_core.config.legacy import from_namespace

    values = from_namespace(
        Namespace(pseudolabel_replay=True, pseudolabel_replay_compute_stress=True)
    )
    assert values["finetune"]["pseudolabels"] == {
        "enabled": True,
        "stress_if_missing": True,
    }


def test_a_head_s_weight_does_not_reach_its_written_labels(foundation, tmp_path):
    config = fine_tune(tmp_path / "run", foundation)
    heads = dict(config.data.heads)
    heads["replay"] = heads["replay"].model_copy(update={"weight": 0.5})
    config = config.model_copy(
        update={"data": config.data.model_copy(update={"heads": heads})}
    )
    built = build(config)
    labelled, _ = load_pseudolabel_artifact(
        tmp_path / "run" / "pseudolabels" / "replay"
    )
    assert {item.weight for item in labelled} == {1.0}
    assert built is not None


def test_the_labels_live_nowhere_but_the_run(foundation, tmp_path):
    config = fine_tune(tmp_path / "run", foundation)
    build(config)
    written = sorted(
        str(path.relative_to(tmp_path))
        for path in Path(tmp_path).rglob("*.safetensors")
    )
    assert "run/pseudolabels/replay/labels.safetensors" in written
